50	const BASE_PREMIUMS = {
51	  sword: 100,
52	  amulet: 60,
53	  staff: 80,
54	  potion: 40,
55	  rune: 25,
56	  moonstone: 25,
57	} as const satisfies Record<string, number>;
58	
59	type InsurableItemType = keyof typeof BASE_PREMIUMS;
60	
61	const isInsurable = (type: string): type is InsurableItemType =>
62	  type in BASE_PREMIUMS;
63	
64	/**
65	 * The single gate every per-type lookup passes through: an item the MHPCO does
66	 * not insure is rejected here rather than yielding an undefined rate later.
67	 */
68	const insurableTypeOf = (item: Item): InsurableItemType => {
69	  if (!isInsurable(item.type)) {
70	    throw new Error(`The MHPCO does not insure a ${item.type}`);
71	  }
72	  return item.type;
73	};
74	
75	const basePremiumOf = (item: Item): number =>
76	  BASE_PREMIUMS[insurableTypeOf(item)];
77	
78	/** Premiums are rounded up — in MHPCO's favour. */
79	const roundPremium = (amount: number): number => Math.ceil(amount);
80	
81	const COMPONENT_BLOCK_SIZE = 3;
82	const COMPONENT_BLOCK_PREMIUM = 60;
83	
84	/** Items of a single type, kept together so the block rule can be applied. */
85	type SameTypeGroup = Item[];
86	
87	const groupByType = (items: Item[]): SameTypeGroup[] => {
88	  const groups = new Map<string, SameTypeGroup>();
89	  for (const item of items) {
90	    const group = groups.get(item.type) ?? [];
91	    group.push(item);
92	    groups.set(item.type, group);
93	  }
94	  return [...groups.values()];
95	};
96	
97	const sumBasePremiums = (group: SameTypeGroup): number =>
98	  group.reduce((sum, item) => sum + basePremiumOf(item), 0);
99	
100	/**
101	 * Exactly three alike items form a building block priced at a flat premium;
102	 * any other count is priced per item.
103	 */
104	const blockAwareBasePremium = (group: SameTypeGroup): number =>
105	  group.length === COMPONENT_BLOCK_SIZE
106	    ? COMPONENT_BLOCK_PREMIUM
107	    : sumBasePremiums(group);
108	
109	const policyBasePremiumFor = (items: Item[]): number =>
110	  groupByType(items).reduce(
111	    (sum, group) => sum + blockAwareBasePremium(group),
112	    0,
113	  );
114	
115	const HIGH_ENCHANTMENT_LEVEL = 5;
116	
117	const isCursed = (item: Item): boolean => item.cursed === true;
118	const isHighlyEnchanted = (item: Item): boolean =>
119	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
120	
121	/**
122	 * An item-specific surcharge: when the item triggers the clause, it is charged
123	 * a rate of that item's own base premium — never of the whole policy's.
124	 */
125	interface ItemSurcharge {
126	  appliesTo: (item: Item) => boolean;
127	  rate: number;
128	}
129	
130	const ITEM_SURCHARGES: ItemSurcharge[] = [
131	  { appliesTo: isCursed, rate: 0.5 },
132	  { appliesTo: isHighlyEnchanted, rate: 0.3 },
133	];
134	
135	/** Every clause the item triggers stacks, each on that item's base premium. */
136	const surchargeRateFor = (item: Item): number =>
137	  ITEM_SURCHARGES.reduce(
138	    (rate, surcharge) =>
139	      surcharge.appliesTo(item) ? rate + surcharge.rate : rate,
140	    0,
141	  );
142	
143	const itemSurchargesFor = (items: Item[]): number =>
144	  items.reduce(
145	    (sum, item) => sum + basePremiumOf(item) * surchargeRateFor(item),
146	    0,
147	  );
148	
149	/** Every quote is an initial assessment, so this surcharge always applies. */
150	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
151	const LOYALTY_DISCOUNT_RATE = -0.2;
152	const LOYALTY_YEARS = 2;
153	
154	const FOLLOW_UP_DISCOUNT_RATE = -0.15;
155	
156	/** What the MHPCO knows about the customer when pricing a particular quote. */
157	interface QuoteContext {
158	  customer: Customer;
159	  previousContracts: number;
160	}
161	
162	const isLoyal = ({ customer }: QuoteContext): boolean =>
163	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
164	const isFollowUpContract = ({ previousContracts }: QuoteContext): boolean =>
165	  previousContracts > 0;
166	
167	/**
168	 * A policy-wide modifier: when the customer triggers the clause, the whole
169	 * policy's base premium is adjusted by that rate — never a single item's.
170	 * A negative rate is a discount.
171	 */
172	interface PolicyModifier {
173	  appliesTo: (context: QuoteContext) => boolean;
174	  rate: number;
175	}
176	
177	/** Conditional clauses, on top of the surcharge every quote already carries. */
178	const POLICY_MODIFIERS: PolicyModifier[] = [
179	  { appliesTo: isLoyal, rate: LOYALTY_DISCOUNT_RATE },
180	  { appliesTo: isFollowUpContract, rate: FOLLOW_UP_DISCOUNT_RATE },
181	];
182	
183	/** Every clause the customer triggers stacks on the policy base premium. */
184	const policyModifierRateFor = (context: QuoteContext): number =>
185	  POLICY_MODIFIERS.reduce(
186	    (rate, modifier) =>
187	      modifier.appliesTo(context) ? rate + modifier.rate : rate,
188	    FIRST_INSURANCE_SURCHARGE_RATE,
189	  );
190	
191	const quotePremium = (items: Item[], context: QuoteContext): number => {
192	  const policyBasePremium = policyBasePremiumFor(items);
193	  return roundPremium(
194	    policyBasePremium +
195	      policyBasePremium * policyModifierRateFor(context) +
196	      itemSurchargesFor(items) +
197	      PROCESSING_FEE,
198	  );
199	};
