303	    if (step.op === "quote") {
304	      const context = { customer: scenario.customer, previousContracts };
305	      previousContracts += 1;
306	      policies.set(index, openPolicy(step.items));
307	      return { premium: quotePremium(step.items, context) };
308	    }
309	
310	    const policy = policies.get(step.policy);
311	    if (policy === undefined) {
312	      throw new Error(`No policy created by step ${step.policy}`);
313	    }
314	    const settlement = settleClaim(policy, step.incident);
315	    policies.set(step.policy, settlement.policy);
316	    return settlement.result;
317	  });
318	
319	  return { results };
320	};
