/**
 * What the MHPCO has on its books partway through a scenario: the policies
 * opened so far, keyed by the step that opened them, and how many contracts the
 * customer has already signed (which decides the follow-up discount).
 */
class Ledger {
  private readonly policies = new Map<number, Policy>();
  private previousContracts = 0;

  quoteContext(customer: Customer): QuoteContext {
    return { customer, previousContracts: this.previousContracts };
  }

  openPolicyAt(step: number, items: Item[]): void {
    this.policies.set(step, openPolicy(items));
    this.previousContracts += 1;
  }

  /** A claim may only draw on a policy an earlier quote step actually opened. */
  policyAt(step: number): Policy {
    const policy = this.policies.get(step);
    if (policy === undefined) {
      throw new Error(`No policy created by step ${step}`);
    }
    return policy;
  }

  drawDownPolicyAt(step: number, policy: Policy): void {
    this.policies.set(step, policy);
  }
}

const runQuoteStep = (
  step: QuoteStep,
  index: number,
  customer: Customer,
  ledger: Ledger,
): StepResult => {
  const context = ledger.quoteContext(customer);
  ledger.openPolicyAt(index, step.items);
  return { premium: quotePremium(step.items, context) };
};

const runClaimStep = (step: ClaimStep, ledger: Ledger): StepResult => {
  const settlement = settleClaim(ledger.policyAt(step.policy), step.incident);
  ledger.drawDownPolicyAt(step.policy, settlement.policy);
  return settlement.result;
};

export const runScenario = (scenario: Scenario): ScenarioResult => {
  const ledger = new Ledger();
  return {
    results: scenario.steps.map((step, index) =>
      step.op === "quote"
        ? runQuoteStep(step, index, scenario.customer, ledger)
        : runClaimStep(step, ledger),
    ),
  };
};

